const POKEMON_SPRITE_IDS = _POKEMON_SPRITE_IDS as Record<string, number>;

const SORT_LABEL_KEYS: Record<string, string> = {
  id: 'pokedex.sortNumber',
  name: 'pokedex.sortName',
  rarity: 'pokedex.sortRarity',
  count: 'pokedex.sortOwned',
  type: 'pokedex.sortType',
};

const ROMAN_GENS = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX'];

const STAT_ACCENT_COLORS: Record<string, string> = {
  defense_mult: '#4ade80',
  spdefense_mult: '#4ade80',
  max_hp_mult: '#4ade80',
  hp_regen_per_turn: '#4ade80',
  attack_mult: '#f87171',
  spattack_mult: '#f87171',
  damage_mult: '#f87171',
  xp_mult: '#38bdf8',
  gold_mult: '#fbbf24',
  egg_drop_chance: '#fbbf24',
  speed_mult: '#c084fc',
  respawn_delay_reduction: '#c084fc',
  expedition_time_reduction: '#c084fc',
  crit_chance: '#fb923c',
  crit_damage_mult: '#fb923c',
  status_proc_mult: '#e879f9',
  rocket_gps_mult: '#ef4444',
};

function pokedexT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(`pokedex.${key}`);
    if (translated && translated !== `pokedex.${key}`) return translated;
  }
  return fallback;
}

function genT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(`generations.${key}`);
    if (translated && translated !== `generations.${key}`) return translated;
  }
  return fallback;
}

