function buildSortButtons(game: GameRuntime): PokedexSortButtonSnapshot[] {
  const keys = ['id', 'name', 'rarity', 'count', 'type'] as const;
  const fallbacks: Record<string, string> = {
    id: 'Numéro',
    name: 'Nom',
    rarity: 'Rareté',
    count: 'Obtenus',
    type: 'Type',
  };
  return keys.map((key) => ({
    key,
    label: (typeof game.t === 'function'
      ? game.t(SORT_LABEL_KEYS[key] ?? '')
      : fallbacks[key]) || fallbacks[key] || key,
    active: game.pokedexSortBy === key,
    order: game.pokedexSortBy === key ? (game.pokedexSortOrder === 'asc' ? 'asc' : 'desc') : null,
  }));
}

function readPokedexGenFilter(game: GameRuntime): string {
  if (game.pokedexGenFilter !== undefined && game.pokedexGenFilter !== null) {
    return String(game.pokedexGenFilter);
  }
  if (typeof document !== 'undefined') {
    const genFilter = document.getElementById('pokedexGenFilter') as HTMLSelectElement | null;
    if (genFilter?.value) return genFilter.value;
  }
  return game.collectionBonusGenFilter || 'all';
}

function readPokedexSearchText(): string {
  if (typeof document === 'undefined') return '';
  const searchInput = document.getElementById('pokedexSearchInput') as HTMLInputElement | null;
  return searchInput?.value?.toLowerCase() ?? '';
}

function buildGenChips(game: GameRuntime, selectedGen: string): PokedexGenChipSnapshot[] {
  const discoveredSet = new Set<string>();
  for (const entry of Object.values(game.pokedex || {})) {
    if (entry && entry.name && (entry.discovered || entry.count)) {
      discoveredSet.add(entry.name);
    }
  }

  const totalsByGen: number[] = Array.from({ length: 10 }, () => 0);
  const discoveredByGen: number[] = Array.from({ length: 10 }, () => 0);

  for (const [name, dexId] of Object.entries(POKEMON_SPRITE_IDS)) {
    if (NON_DEX_SPRITE_PLACEHOLDERS.has(name)) continue;
    const gen = getNationalDexGeneration(dexId);
    if (gen != null && gen >= 1 && gen <= 9) {
      totalsByGen[gen] = (totalsByGen[gen] ?? 0) + 1;
      totalsByGen[0] = (totalsByGen[0] ?? 0) + 1;
      if (discoveredSet.has(name)) {
        discoveredByGen[gen] = (discoveredByGen[gen] ?? 0) + 1;
        discoveredByGen[0] = (discoveredByGen[0] ?? 0) + 1;
      }
    }
  }

  const chips: PokedexGenChipSnapshot[] = [];
  const allTotal = totalsByGen[0] ?? 0;
  const allDiscovered = discoveredByGen[0] ?? 0;
  chips.push({
    value: 'all',
    label: pokedexT(game, 'genAllShort', 'Toutes'),
    title: `Total : ${allDiscovered}/${allTotal}`,
    discovered: allDiscovered,
    total: allTotal,
    isComplete: allDiscovered >= allTotal && allTotal > 0,
    active: selectedGen === 'all',
  });

  for (let g = 1; g <= 9; g++) {
    const tot = totalsByGen[g] ?? 0;
    const disc = discoveredByGen[g] ?? 0;
    const roman = ROMAN_GENS[g - 1] ?? String(g);
    const isComplete = disc >= tot && tot > 0;
    const pct = tot > 0 ? Math.round((disc / tot) * 100) : 0;
    chips.push({
      value: String(g),
      label: roman,
      title: `Gen ${roman} : ${disc}/${tot} (${pct} %)`,
      discovered: disc,
      total: tot,
      isComplete,
      active: selectedGen === String(g),
    });
  }

  return chips;
}

function buildCollectionGlobalSummaryHtml(
  game: GameRuntime,
  details: CollectionBonusDetail[],
): string {
  const isEn = game && typeof game.normalizeLanguage === 'function'
    ? game.normalizeLanguage(game.language) === 'en'
    : false;

  const activeFams = details.filter((f) => f.isActive);
  const activeCount = activeFams.length;

  if (activeCount === 0) {
    const noneText = pokedexT(
      game,
      'collectionActiveSummaryNone',
      'Aucun bonus actif (montez tous les membres d’une collection au Prestige 1+)',
    );
    return `<div class="collection-global-summary is-empty"><span class="coll-summary-hint">${noneText}</span></div>`;
  }

  const chips: string[] = [];
  activeFams.forEach((fam) => {
    const primaryKey = fam.primaryEffectKey || 'misc';
    const accentColor = STAT_ACCENT_COLORS[primaryKey] || '#94a3b8';
    const effectText = fam.currentEffectSummary || (fam.effectTexts[0] ?? '');
    if (effectText) {
      chips.push(
        `<span class="coll-summary-chip" style="border-left: 2px solid ${accentColor};" title="${fam.name} (Niv. ${fam.level})">${effectText}</span>`,
      );
    }
  });

  const titleText = pokedexT(game, 'collectionActiveSummaryTitle', 'Bonus actifs');
  const summaryChips = chips.slice(0, 5).join(' ');
  const remainingCount = chips.length > 5 ? chips.length - 5 : 0;
  const moreText = remainingCount > 0 ? `<span class="coll-summary-more">+${remainingCount} autres</span>` : '';

  return `<details class="collection-global-summary">
    <summary class="coll-summary-header">
      <span class="coll-summary-title">⚡ ${titleText} <strong class="coll-summary-count">(${activeCount})</strong> :</span>
      <span class="coll-summary-preview">${summaryChips} ${moreText}</span>
      <span class="coll-summary-toggle">▾</span>
    </summary>
    <div class="coll-summary-expanded">
      ${chips.join(' ')}
    </div>
  </details>`;
}

function buildCollectionBonusesParts(game: GameRuntime, selectedGen: string): Pick<
  PokedexSnapshot,
  'collectionToolbarHtml' | 'collectionTabsHtml' | 'collectionTabsClass' | 'collectionBonusesHtml' | 'collectionGlobalSummaryHtml'
> {
  const empty = {
    collectionToolbarHtml: '',
    collectionTabsHtml: '',
    collectionTabsClass: 'collection-bonus-tabs',
    collectionBonusesHtml: '',
    collectionGlobalSummaryHtml: '',
  };
  const t = (key: string, fallback: string) => pokedexT(game, key, fallback);
  const labels = {
    all: t('collectionTabAll', 'Tous'),
    none: t('collectionEffectNone', 'aucun'),
    bonusPerPrestigeTitle: t('collectionBonusPerPrestigeTitle', 'Bonus par niveau de collection'),
    levelShort: t('collectionLevelShort', 'Niv.'),
    missing: t('collectionMissing', 'manquant'),
    missingPlural: t('collectionMissingPlural', 'manquants'),
    needsShiny: t('collectionNeedsShiny', 'chromatique requis'),
    needsShinyPlural: t('collectionNeedsShinyPlural', 'chromatiques requis'),
    prestigeZero: t('collectionPrestigeZero', 'prestige 0'),
    incomplete: t('collectionIncomplete', 'incomplet'),
    notOwned: t('collectionNotOwned', 'Non possédé'),
    needsShinyOwned: t('collectionNeedsShinyOwned', 'Chromatique requis'),
    showAllCollections: t('collectionShowAll', 'Filtrer par collection ▾'),
    foldCollections: t('collectionFold', 'Masquer la liste ▲'),
  };

  if (typeof game.getCollectionBonusDetails !== 'function') return empty;
  const rawDetails = game.getCollectionBonusDetails();
  if (!rawDetails || rawDetails.length === 0) return empty;

  const ownershipRaw = (game.collectionBonusOwnershipFilter || 'all') as CollectionOwnershipFilter;
  const ownershipFilter: CollectionOwnershipFilter =
    ['completable', 'almost', 'active'].includes(ownershipRaw) ? ownershipRaw : 'all';

  const details = filterAndSortCollectionDetails(rawDetails, {
    genFilter: selectedGen,
    ownershipFilter,
    getFamilySortName: (fam) => fam.name,
    sortMode: 'progress',
  });

  const collectionGlobalSummaryHtml = buildCollectionGlobalSummaryHtml(game, rawDetails);

  const tab = game.collectionBonusTab || 'all';
  const filteredDetails = tab === 'all' ? details : details.filter((f) => f.id === tab);
  const collapseThreshold = 8;
  const needsFold = details.length > collapseThreshold;
  if (!needsFold) {
    game.collectionBonusTabsCollapsed = false;
  } else if (typeof game.collectionBonusTabsCollapsed !== 'boolean') {
    game.collectionBonusTabsCollapsed = true;
  }
  const isTabsCollapsed = needsFold ? !!game.collectionBonusTabsCollapsed : false;

  let collectionToolbarHtml = '';
  if (needsFold) {
    collectionToolbarHtml = `<button class="sort-btn collection-tabs-toggle-btn" data-action="toggleCollectionBonusTabs" style="font-size:12px; padding:6px 10px;">${isTabsCollapsed ? labels.showAllCollections : labels.foldCollections}</button>`;
  }

  const tabClasses = [
    'collection-bonus-tabs',
    needsFold ? 'is-collapsible' : '',
    needsFold && isTabsCollapsed ? 'is-collapsed' : '',
    needsFold && !isTabsCollapsed ? 'is-expanded' : '',
    needsFold && isTabsCollapsed ? 'is-hidden' : '',
  ].filter(Boolean).join(' ');

  let collectionTabsHtml = '';
  if (!(needsFold && isTabsCollapsed)) {
    collectionTabsHtml = `<button class="sort-btn ${tab === 'all' ? 'active' : ''}" data-action="setCollectionBonusTabAll" style="font-size:12px; padding:6px 10px;">${labels.all}</button>`;
    details.forEach((fam) => {
      const isActive = tab === fam.id;
      collectionTabsHtml += `<button class="sort-btn ${isActive ? 'active' : ''}" data-action="setCollectionBonusTab" data-arg="${fam.id}" style="font-size:12px; padding:6px 10px;">${fam.name}</button>`;
    });
  }

  let collectionBonusesHtml = '';
  if (filteredDetails.length === 0) {
    const emptyMsg = t('collectionEmptyFiltered', 'Aucune collection ne correspond à ces filtres.');
    collectionBonusesHtml = `<p class="collection-bonus-empty-filtered" style="font-size:13px; color:#94a3b8; padding:16px 0; text-align:center;">${emptyMsg}</p>`;
    return {
      collectionToolbarHtml,
      collectionTabsHtml,
      collectionTabsClass: tabClasses,
      collectionBonusesHtml,
      collectionGlobalSummaryHtml,
    };
  }

  filteredDetails.forEach((fam) => {
    const statusClass = fam.isActive ? 'synergy-active is-active' : 'synergy-inactive is-inactive';
    const primaryKey = fam.primaryEffectKey || 'misc';
    const accentColor = STAT_ACCENT_COLORS[primaryKey] || '#94a3b8';

    const metrics = computeCollectionProgressMetrics(fam);
    const progressPct = Math.round(metrics.progressRatio * 100);

    const currentBonusText = fam.currentEffectSummary || (fam.effectTexts[0] ?? '+0%');
    let nextBonusText = fam.nextEffectSummary;
    if (fam.level >= 9) {
      nextBonusText = null;
    }

    let progressStatusText = '';
    if (fam.level === 0) {
      if (metrics.ownedSpeciesCount < metrics.totalMembers) {
        progressStatusText = `${metrics.ownedSpeciesCount}/${metrics.totalMembers} espèces possédées`;
      } else {
        const p1Count = fam.members.filter((m) => m.status === 'ok').length;
        progressStatusText = `${p1Count}/${metrics.totalMembers} au Prestige 1+ (débloque Niv. 1)`;
      }
    } else if (fam.level >= 9) {
      progressStatusText = 'Niveau Maximum (9/9) atteint !';
    } else {
      const targetP = fam.level + 1;
      progressStatusText = `Objectif Niv. ${targetP} : ${metrics.readyForNextCount}/${metrics.totalMembers} membres au Prestige ${targetP}+`;
    }

    collectionBonusesHtml += `<div class="collection-bonus-card ${statusClass}" style="--coll-accent:${accentColor};">
            <div class="collection-card-header">
                <div class="collection-card-title-group">
                    <span class="collection-level-badge ${fam.isActive ? 'is-active' : 'is-zero'}">${labels.levelShort} ${fam.level}</span>
                    <h4 class="collection-card-title">${fam.name}</h4>
                </div>
                <div class="collection-card-bonus-progression" title="${fam.bonusPerPrestige || ''}">
                    <span class="coll-bonus-current ${fam.isActive ? 'is-active' : 'is-zero'}">${currentBonusText}</span>
                    ${nextBonusText ? `<span class="coll-bonus-arrow">→</span><span class="coll-bonus-next" style="color:${accentColor}">${nextBonusText}</span>` : '<span class="coll-bonus-max">MAX</span>'}
                </div>
            </div>
            <div class="collection-card-progress-row">
                <div class="collection-progress-bar">
                    <div class="collection-progress-fill" style="width:${progressPct}%; background:${accentColor};"></div>
                </div>
                <span class="collection-progress-label">${progressStatusText}</span>
            </div>
            <div class="collection-bonus-grid">`;

    fam.members.forEach((m) => {
      const rarity = typeof game.getNaturalRarity === 'function' ? game.getNaturalRarity(m.name) : 'common';
      const rClass = `rarity-${rarity || 'common'}`;
      const showShinySprite = !!(m.shinyRequired || m.status === 'needs_shiny');
      const spriteUrl = capturePreviewSpriteUrl(m.name, showShinySprite);
      const memberDisplayName = uiPokemonName(game, m.name);

      const title = m.status === 'missing'
        ? `${memberDisplayName} : ${labels.notOwned} (cliquer pour voir où l'obtenir)`
        : (m.status === 'needs_shiny'
          ? `${memberDisplayName} : ${labels.needsShinyOwned}`
          : (m.status === 'prestige_0'
            ? game.t('pokedex.collectionMemberPrestigeZero', { name: memberDisplayName })
            : game.t('pokedex.collectionMemberPrestige', { name: memberDisplayName, prestige: String(m.prestige) })));

      const badgeHtml = m.status === 'ok'
        ? `<span class="coll-member-badge is-ok">★${m.prestige}</span>`
        : (m.status === 'prestige_0'
          ? '<span class="coll-member-badge is-p0">★0</span>'
          : (m.status === 'needs_shiny'
            ? '<span class="coll-member-badge is-shiny-req">✦?</span>'
            : '<span class="coll-member-badge is-missing">—</span>'));

      const isSilhouette = m.status === 'missing';
      const imgClass = `coll-member-sprite ${isSilhouette ? 'is-silhouette' : ''}`;
      const encodedArg = encodeURIComponent(m.name);

      collectionBonusesHtml += `<div class="collection-member-card ${rClass} status-${m.status}"
                data-action="openPokedexAcquisitionDetail"
                data-arg="${encodedArg}"
                role="button"
                tabindex="0"
                title="${title}">
                <img src="${spriteUrl}" alt="${memberDisplayName}" class="${imgClass}" onerror="this.style.display='none'">
                ${badgeHtml}
            </div>`;
    });
    collectionBonusesHtml += '</div></div>';
  });

  return {
    collectionToolbarHtml,
    collectionTabsHtml,
    collectionTabsClass: tabClasses,
    collectionBonusesHtml,
    collectionGlobalSummaryHtml,
  };
}

interface PokedexEntryRow {
  name: string;
  rarity?: string;
  type?: string;
  hasShiny?: boolean;
  hasShadow?: boolean;
  count?: number;
  shinyCount?: number;
  shadowCount?: number;
  firstDiscoveredAt?: number;
}

function getSortedPokedexEntriesWithKeys(
  game: GameRuntime,
): Array<{ storageKey: string; entry: PokedexEntryRow }> {
  const pairs = Object.entries(game.pokedex || {}) as Array<[string, PokedexEntryRow]>;
  const sortBy = game.pokedexSortBy || 'id';
  const order = game.pokedexSortOrder === 'asc' ? 1 : -1;
  return [...pairs].sort(([, a], [, b]) => {
    let valA: number | string;
    let valB: number | string;
    switch (sortBy) {
      case 'id': {
        valA = getSpriteIdForSpecies(a.name) || 9999;
        valB = getSpriteIdForSpecies(b.name) || 9999;
        return ((valA) - (valB)) * order;
      }
      case 'name': {
        const isFr = game && typeof game.normalizeLanguage === 'function'
          ? game.normalizeLanguage(game.language) !== 'en'
          : true;
        if (isFr) {
          return uiPokemonName(game, a.name).localeCompare(uiPokemonName(game, b.name), 'fr') * order;
        }
        return a.name.localeCompare(b.name, 'en') * order;
      }
      case 'rarity': {
        const rarityOrder: Record<string, number> = { common: 1, rare: 2, epic: 3, legendary: 4 };
        valA = rarityOrder[a.rarity || ''] || 0;
        valB = rarityOrder[b.rarity || ''] || 0;
        return ((valA) - (valB)) * order;
      }
      case 'count':
        return ((a.count || 0) - (b.count || 0)) * order;
      case 'type':
        return (a.type || '').localeCompare(b.type || '') * order;
      default:
        return 0;
    }
  }).map(([storageKey, entry]) => ({ storageKey, entry }));
}

function buildPokedexCards(
  game: GameRuntime,
  selectedGen: string,
  searchText: string,
): PokedexCardSnapshot[] {
  const isEn = game && typeof game.normalizeLanguage === 'function'
    ? game.normalizeLanguage(game.language) === 'en'
    : false;
  const locale = isEn ? 'en-US' : 'fr-FR';

  if (game.pokedexFilterMissing) {
    const discoveredNames = new Set<string>();
    for (const e of Object.values(game.pokedex || {})) {
      if (e && e.name && (e.discovered || e.count)) {
        discoveredNames.add(e.name);
      }
    }

    const missingEntries: Array<{ name: string; dexId: number }> = [];
    for (const [name, dexId] of Object.entries(POKEMON_SPRITE_IDS)) {
      if (NON_DEX_SPRITE_PLACEHOLDERS.has(name)) continue;
      if (discoveredNames.has(name)) continue;
      if (!matchesGenerationFilter(name, selectedGen)) continue;
      if (searchText) {
        const localized = uiPokemonName(game, name).toLowerCase();
        if (!name.toLowerCase().includes(searchText) && !localized.includes(searchText)) {
          continue;
        }
      }
      missingEntries.push({ name, dexId: Number(dexId) || 9999 });
    }

    missingEntries.sort((a, b) => a.dexId - b.dexId);

    return missingEntries.map(({ name, dexId }) => {
      const formattedId = dexId < 9999 ? `#${dexId.toString().padStart(3, '0')}` : '?';
      const naturalRarity = typeof game.getNaturalRarity === 'function' ? game.getNaturalRarity(name) : 'common';
      const localizedName = uiPokemonName(game, name);
      const notDiscoveredLabel = pokedexT(game, 'notDiscovered', 'Non découvert');
      const clickSourcesLabel = pokedexT(game, 'clickForSources', 'Cliquer pour voir les sources d’obtention');

      return {
        cardKey: `missing_${name}`,
        name,
        displayName: '???',
        type: '',
        rarity: naturalRarity,
        hasShiny: false,
        hasShadow: false,
        count: 0,
        shinyCount: 0,
        shadowCount: 0,
        countFormatted: '0',
        shinyCountFormatted: '0',
        shadowCountFormatted: '0',
        formattedId,
        spriteUrl: capturePreviewSpriteUrl(name, false),
        discoveryDate: '',
        encodedArg: encodeURIComponent(name),
        capturedLabel: game.t('pokedex.capturedLabel'),
        shinyCapturedLabel: game.t('pokedex.shinyCapturedLabel'),
        shadowCapturedLabel: game.t('pokedex.shadowCapturedLabel'),
        shinyBadgeTitle: game.t('pokedex.shinyBadge'),
        shadowBadgeTitle: game.t('pokedex.shadowBadge'),
        cardAriaLabel: `${notDiscoveredLabel} : ${localizedName} (${formattedId})`,
        isDiscovered: false,
        tooltipText: `${localizedName} (${formattedId})\n${notDiscoveredLabel} — ${clickSourcesLabel}`,
      };
    });
  }

  let entries = getSortedPokedexEntriesWithKeys(game)
    .filter(({ entry }) => entry && entry.name)
    .filter(({ entry }) => isKnownSpecies(entry.name))
    .filter(({ entry }) => matchesGenerationFilter(entry.name, selectedGen))
    .filter(({ entry }) => {
      if (!searchText) return true;
      const localized = uiPokemonName(game, entry.name).toLowerCase();
      return entry.name.toLowerCase().includes(searchText) || localized.includes(searchText);
    });

  if (game.pokedexFilterShiny) {
    entries = entries.filter(({ entry }) => !!entry.hasShiny);
  }

  return entries.map(({ storageKey, entry }) => {
    let formattedId = '?';
    const dexId = getSpriteIdForSpecies(entry.name);
    if (dexId) formattedId = `#${dexId.toString().padStart(3, '0')}`;
    let discoveryDate = game.t('pokedex.unknownDate');
    if (entry.firstDiscoveredAt) {
      discoveryDate = new Date(entry.firstDiscoveredAt).toLocaleDateString(locale);
    }
    const displayName = uiPokemonName(game, entry.name);
    const count = entry.count || 1;
    const shinyCount = entry.shinyCount || 1;
    const shadowCount = entry.shadowCount || 1;

    const countFormatted = Number(count).toLocaleString(locale);
    const shinyCountFormatted = Number(shinyCount).toLocaleString(locale);
    const shadowCountFormatted = Number(shadowCount).toLocaleString(locale);

    const capturedLbl = game.t('pokedex.capturedLabel') || 'Captures';
    const firstLbl = game.t('pokedex.firstCaptureLabel') || 'Première capture';
    const shinyLbl = game.t('pokedex.shinyCapturedLabel') || 'Dont Shinies';

    const shinyTip = entry.hasShiny ? ` · ✦ ${shinyCountFormatted}` : '';
    const dateTip = entry.firstDiscoveredAt ? ` · ${firstLbl} : ${discoveryDate}` : '';
    const tooltipText = `${displayName} (${formattedId})\n${capturedLbl} : ${countFormatted}${shinyTip}${dateTip}`;

    return {
      cardKey: storageKey,
      name: entry.name,
      displayName,
      type: entry.type || '',
      rarity: entry.rarity || 'common',
      hasShiny: !!entry.hasShiny,
      hasShadow: !!entry.hasShadow,
      count,
      shinyCount,
      shadowCount,
      countFormatted,
      shinyCountFormatted,
      shadowCountFormatted,
      formattedId,
      spriteUrl: capturePreviewSpriteUrl(entry.name, false),
      discoveryDate,
      encodedArg: encodeURIComponent(entry.name),
      capturedLabel: capturedLbl,
      shinyCapturedLabel: shinyLbl,
      shadowCapturedLabel: game.t('pokedex.shadowCapturedLabel'),
      shinyBadgeTitle: game.t('pokedex.shinyBadge'),
      shadowBadgeTitle: game.t('pokedex.shadowBadge'),
      cardAriaLabel: game.t('pokedex.acquisitionCardAria', { name: displayName }),
      isDiscovered: true,
      tooltipText,
    };
  });
}

export function buildPokedexSnapshot(game: GameRuntime): PokedexSnapshot {
  const selectedGen = readPokedexGenFilter(game);
  const searchText = readPokedexSearchText();
  const cards = buildPokedexCards(game, selectedGen, searchText);

  const activeSubTab =
    game.pokedexSubTab === 'collectionbonuses' ? 'collectionbonuses' : 'pokedex';
  const hasPokedexEntries = Object.keys(game.pokedex || {}).length > 0;
  const cardsEmptyMessage = hasPokedexEntries
    ? game.t('pokedex.emptyFiltered')
    : game.t('pokedex.emptyRepairPrompt');

  const totalPossibleSpecies = Object.keys(POKEMON_SPRITE_IDS).filter(
    (name) => !NON_DEX_SPRITE_PLACEHOLDERS.has(name),
  ).length;

  const discoveredCount = countPokedexUniqueDiscovered(game.pokedex);
  const pokedexPercent = totalPossibleSpecies > 0
    ? Math.round((discoveredCount / totalPossibleSpecies) * 100)
    : 0;
  const missingCount = Math.max(0, totalPossibleSpecies - discoveredCount);
  const isEn = game && typeof game.normalizeLanguage === 'function'
    ? game.normalizeLanguage(game.language) === 'en'
    : false;
  const locale = isEn ? 'en-US' : 'fr-FR';
  const pokedexMissingCount = Number(missingCount).toLocaleString(locale);

  const genChips = buildGenChips(game, selectedGen);

  return {
    languageTag: (game && typeof game.normalizeLanguage === 'function')
      ? game.normalizeLanguage(game.language)
      : 'fr',
    ui: buildPokedexPanelUi(game),
    pokedexCount: String(discoveredCount),
    pokedexTotal: String(totalPossibleSpecies),
    pokedexPercent,
    pokedexMissingCount,
    selectedGen,
    filterMissingActive: !!game.pokedexFilterMissing,
    filterShinyActive: !!game.pokedexFilterShiny,
    genChips,
    collectionOwnershipFilter: game.collectionBonusOwnershipFilter || 'all',
    activeSubTab,
    sortButtons: buildSortButtons(game),
    ...buildCollectionBonusesParts(game, selectedGen),
    cards,
    cardsEmptyMessage,
  };
}

let lastPokedexSnapshot: PokedexSnapshot | null = null;

/** @internal Vitest only */
export function resetPokedexSnapshotDedupForTests(): void {
  lastPokedexSnapshot = null;
}

export function notifyPokedexChanged(game: GameRuntime): void {
  const pokedex = buildPokedexSnapshot(game);
  if (lastPokedexSnapshot && !pokedexSnapshotWouldChange(lastPokedexSnapshot, pokedex)) return;
  lastPokedexSnapshot = pokedex;
  publish({ type: Evt.POKEDEX_CHANGED, pokedex });
}
