/**
 * @file collectionBonusFilters.ts
 * Generation and ownership filters + sort for Pokédex collection bonus families.
 */

import type { CollectionBonusDetail } from '../types/game.js';
import { getSpeciesGeneration, matchesGenerationFilter } from './nationalDexGeneration.js';

export type CollectionOwnershipFilter = 'all' | 'completable' | 'almost' | 'active';

export interface CollectionBonusFilterOptions {
  genFilter: string;
  ownershipFilter: CollectionOwnershipFilter;
  /** Compare localized family names when sorting */
  getFamilySortName: (detail: CollectionBonusDetail) => string;
  /** Sort mode: 'default' (primary gen then name) or 'progress' (progress ratio desc) */
  sortMode?: 'default' | 'progress';
}

export interface CollectionProgressMetrics {
  totalMembers: number;
  ownedSpeciesCount: number;
  readyForNextCount: number;
  progressRatio: number;
  isMaxLevel: boolean;
  isAlmostComplete: boolean;
}

export function getMemberNames(
  members: CollectionBonusDetail['members'],
): string[] {
  return members.map((m) => m.name).filter(Boolean);
}

/** True if at least one member belongs to the selected generation. */
export function collectionMatchesGenerationFilter(
  memberNames: string[],
  selectedGen: string,
): boolean {
  if (!selectedGen || selectedGen === 'all') return true;
  return memberNames.some((name) => matchesGenerationFilter(name, selectedGen));
}

/** Minimum generation among members (999 if none known). */
export function collectionPrimaryGeneration(memberNames: string[]): number {
  let min = 999;
  for (let i = 0; i < memberNames.length; i++) {
    const name = memberNames[i];
    if (name === undefined) continue;
    const gen = getSpeciesGeneration(name);
    if (gen != null && gen < min) min = gen;
  }
  return min;
}

/** All species owned: no member with status `missing` (needs_shiny still counts as owned). */
export function collectionAllSpeciesOwned(
  members: CollectionBonusDetail['members'],
): boolean {
  return members.every((m) => m.status !== 'missing');
}

export function computeCollectionProgressMetrics(
  fam: CollectionBonusDetail,
): CollectionProgressMetrics {
  const totalMembers = fam.members.length;
  if (totalMembers === 0) {
    return {
      totalMembers: 0,
      ownedSpeciesCount: 0,
      readyForNextCount: 0,
      progressRatio: 0,
      isMaxLevel: false,
      isAlmostComplete: false,
    };
  }

  const ownedSpeciesCount = fam.members.filter(
    (m) => m.status !== 'missing' && m.status !== 'needs_shiny',
  ).length;

  const targetPrestige = Math.min(9, (fam.level || 0) + 1);
  const readyForNextCount = fam.members.filter(
    (m) => m.status === 'ok' && (m.prestige || 0) >= targetPrestige,
  ).length;

  const isMaxLevel = (fam.level || 0) >= 9;
  const progressRatio = isMaxLevel
    ? 1
    : (readyForNextCount / totalMembers) * 0.7 + (ownedSpeciesCount / totalMembers) * 0.3;

  const isAlmostComplete =
    !isMaxLevel &&
    (totalMembers - readyForNextCount <= 2 ||
      readyForNextCount / totalMembers >= 0.6 ||
      (fam.level === 0 && ownedSpeciesCount === totalMembers));

  return {
    totalMembers,
    ownedSpeciesCount,
    readyForNextCount,
    progressRatio,
    isMaxLevel,
    isAlmostComplete,
  };
}

export function filterAndSortCollectionDetails(
  details: CollectionBonusDetail[],
  options: CollectionBonusFilterOptions,
): CollectionBonusDetail[] {
  const { genFilter, ownershipFilter, getFamilySortName, sortMode = 'default' } = options;

  let list = details.filter((fam) => {
    const names = getMemberNames(fam.members);
    if (!collectionMatchesGenerationFilter(names, genFilter)) return false;
    if (ownershipFilter === 'completable' && !collectionAllSpeciesOwned(fam.members)) {
      return false;
    }
    if (ownershipFilter === 'active' && !fam.isActive) {
      return false;
    }
    if (ownershipFilter === 'almost') {
      const metrics = computeCollectionProgressMetrics(fam);
      if (!metrics.isAlmostComplete) return false;
    }
    return true;
  });

  list = [...list].sort((a, b) => {
    if (sortMode === 'progress') {
      const metricsA = computeCollectionProgressMetrics(a);
      const metricsB = computeCollectionProgressMetrics(b);
      if (metricsA.isMaxLevel !== metricsB.isMaxLevel) {
        return metricsA.isMaxLevel ? 1 : -1;
      }
      if (Math.abs(metricsB.progressRatio - metricsA.progressRatio) > 0.001) {
        return metricsB.progressRatio - metricsA.progressRatio;
      }
      if (b.level !== a.level) {
        return b.level - a.level;
      }
    }
    const genA = collectionPrimaryGeneration(getMemberNames(a.members));
    const genB = collectionPrimaryGeneration(getMemberNames(b.members));
    if (genA !== genB) return genA - genB;
    return getFamilySortName(a).localeCompare(getFamilySortName(b), undefined, { sensitivity: 'base' });
  });

  return list;
}
